import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_q_network.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_dqn_target.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_target_network.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_replay_buffer.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_training_loop.png",f=JSON.parse('{"title":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环","description":"从 Q-learning（Q 学习）走向 Deep Q-Network（深度 Q 网络，DQN），最直观的变化是把 (Q(s,a)) 表格换成神经网络 (Q(s,a;\\\\theta))。但只完成这次替换，训练往往会振荡甚至发散。网络正在拟合一个由自己生成、持续移动的目标，连续采集的样本高度相关，贪心策","frontmatter":{"title":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环","description":"从 Q-learning（Q 学习）走向 Deep Q-Network（深度 Q 网络，DQN），最直观的变化是把 (Q(s,a)) 表格换成神经网络 (Q(s,a;\\\\theta))。但只完成这次替换，训练往往会振荡甚至发散。网络正在拟合一个由自己生成、持续移动的目标，连续采集的样本高度相关，贪心策","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":15,"source":"2026-08-13/rl_series_11_dqn_foundations.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_11_q_network.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-11-dqn-foundations"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环"}],["meta",{"property":"og:description","content":"从 Q-learning（Q 学习）走向 Deep Q-Network（深度 Q 网络，DQN），最直观的变化是把 (Q(s,a)) 表格换成神经网络 (Q(s,a;\\\\theta))。但只完成这次替换，训练往往会振荡甚至发散。网络正在拟合一个由自己生成、持续移动的目标，连续采集的样本高度相关，贪心策"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-11-dqn-foundations"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_q_network.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环"}],["meta",{"name":"twitter:description","content":"从 Q-learning（Q 学习）走向 Deep Q-Network（深度 Q 网络，DQN），最直观的变化是把 (Q(s,a)) 表格换成神经网络 (Q(s,a;\\\\theta))。但只完成这次替换，训练往往会振荡甚至发散。网络正在拟合一个由自己生成、持续移动的目标，连续采集的样本高度相关，贪心策"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_11_q_network.png"}]],"prev":{"text":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化","link":"/rl/rl-series-10-function-approximation"},"next":{"text":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里","link":"/rl/rl-series-12-dqn-advanced"}},"headers":[],"relativePath":"rl/rl-series-11-dqn-foundations.md","filePath":"rl/rl-series-11-dqn-foundations.md","lastUpdated":null}'),s={name:"rl/rl-series-11-dqn-foundations.md"};function c(p,a,_,u,q,b){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="把-q-表换成神经网络就够了吗-dqn-的完整训练闭环" tabindex="-1">把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环 <a class="header-anchor" href="#把-q-表换成神经网络就够了吗-dqn-的完整训练闭环" aria-label="Permalink to &quot;把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环&quot;">​</a></h1><p>从 Q-learning（Q 学习）走向 Deep Q-Network（深度 Q 网络，DQN），最直观的变化是把 (Q(s,a)) 表格换成神经网络 (Q(s,a;\\theta))。但只完成这次替换，训练往往会振荡甚至发散。网络正在拟合一个由自己生成、持续移动的目标，连续采集的样本高度相关，贪心策略又会改变未来的数据分布，这不是普通的监督学习问题。</p><p>DQN 的关键不是“神经网络加 Q-learning”这句口号，而是一套完整闭环：在线网络给出当前动作价值，Replay Buffer（回放缓冲区）打散并复用历史转移，Target Network（目标网络）提供阶段性稳定的自举目标，ε-greedy（ε-贪心）负责探索。缺少其中任何一环，都可能改变算法含义与训练行为。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-dqn-学的是离散动作价值" tabindex="-1">1.1 DQN 学的是离散动作价值 <a class="header-anchor" href="#_1-1-dqn-学的是离散动作价值" aria-label="Permalink to &quot;1.1 DQN 学的是离散动作价值&quot;">​</a></h3><p>给定状态，网络一次输出所有离散动作的 Q 值，再选择最大值动作。它适合像左、直、右或有限个高层驾驶决策，不直接解决连续方向盘和连续加速度优化。</p><h3 id="_1-2-经验回放降低相关性但不制造独立样本" tabindex="-1">1.2 经验回放降低相关性但不制造独立样本 <a class="header-anchor" href="#_1-2-经验回放降低相关性但不制造独立样本" aria-label="Permalink to &quot;1.2 经验回放降低相关性但不制造独立样本&quot;">​</a></h3><p>缓冲区把不同时刻的转移混在一起随机抽取，降低相邻样本的强相关并提高数据复用率。然而样本仍来自不断变化的行为策略和同一个环境，不能严格称为 Independent and Identically Distributed（独立同分布）。</p><h3 id="_1-3-目标网络缓和移动目标但不保证收敛" tabindex="-1">1.3 目标网络缓和移动目标但不保证收敛 <a class="header-anchor" href="#_1-3-目标网络缓和移动目标但不保证收敛" aria-label="Permalink to &quot;1.3 目标网络缓和移动目标但不保证收敛&quot;">​</a></h3><p>在线网络频繁更新，目标网络延迟同步。目标因此在一段时间内相对固定，回归问题更稳定，但异策略、自举与函数逼近的组合风险仍然存在。</p><h3 id="_1-4-终止语义和评估协议同样属于算法" tabindex="-1">1.4 终止语义和评估协议同样属于算法 <a class="header-anchor" href="#_1-4-终止语义和评估协议同样属于算法" aria-label="Permalink to &quot;1.4 终止语义和评估协议同样属于算法&quot;">​</a></h3><p>自然终止时应停止自举，外部时间截断通常仍应保留下一状态价值。若把两者混为一个 <code>done</code>，目标会产生系统偏差；若评估仍保留探索，也无法看清真正的贪心策略能力。</p><p><img src="'+h+'" alt="DQN 把状态映射为一组离散动作价值"></p><h2 id="二、从-q-表到-q-网络发生了什么" tabindex="-1">二、从 Q 表到 Q 网络发生了什么 <a class="header-anchor" href="#二、从-q-表到-q-网络发生了什么" aria-label="Permalink to &quot;二、从 Q 表到 Q 网络发生了什么&quot;">​</a></h2><h3 id="_2-1-输入从状态索引变成状态表示" tabindex="-1">2.1 输入从状态索引变成状态表示 <a class="header-anchor" href="#_2-1-输入从状态索引变成状态表示" aria-label="Permalink to &quot;2.1 输入从状态索引变成状态表示&quot;">​</a></h3><p>表格用状态编号定位一行，网络接收向量、图像或经过编码的观测。状态表示必须包含完成决策所需的信息，否则网络只会更复杂地拟合不完整观测。</p><h3 id="_2-2-输出对应固定动作集合" tabindex="-1">2.2 输出对应固定动作集合 <a class="header-anchor" href="#_2-2-输出对应固定动作集合" aria-label="Permalink to &quot;2.2 输出对应固定动作集合&quot;">​</a></h3><p>若动作集合为 (\\mathcal A)，常见 DQN 输出维度就是 (|\\mathcal A|)。网络共享前面的状态特征，在输出层分别给出每个动作的价值。</p><h3 id="_2-3-参数共享带来泛化与干扰" tabindex="-1">2.3 参数共享带来泛化与干扰 <a class="header-anchor" href="#_2-3-参数共享带来泛化与干扰" aria-label="Permalink to &quot;2.3 参数共享带来泛化与干扰&quot;">​</a></h3><p>一个状态的更新会改变其他状态的预测。相似场景可以共享经验，但错误梯度也可能扩散到未出现在当前批次的场景，这正是上一篇函数逼近讨论的双面性。</p><h2 id="三、bellman-目标怎样变成训练标签" tabindex="-1">三、Bellman 目标怎样变成训练标签 <a class="header-anchor" href="#三、bellman-目标怎样变成训练标签" aria-label="Permalink to &quot;三、Bellman 目标怎样变成训练标签&quot;">​</a></h2><h3 id="_3-1-一条转移包含五项信息" tabindex="-1">3.1 一条转移包含五项信息 <a class="header-anchor" href="#_3-1-一条转移包含五项信息" aria-label="Permalink to &quot;3.1 一条转移包含五项信息&quot;">​</a></h3><p>训练样本通常保存 ((S_t,A_t,R_{t+1},S_{t+1},D_{t+1}))，其中终止标记决定下一状态价值是否进入目标。</p><h3 id="_3-2-普通-dqn-的一步目标" tabindex="-1">3.2 普通 DQN 的一步目标 <a class="header-anchor" href="#_3-2-普通-dqn-的一步目标" aria-label="Permalink to &quot;3.2 普通 DQN 的一步目标&quot;">​</a></h3><p>对非终止转移，目标为：</p><p>$$ Y_t=R_{t+1}+\\gamma\\max_{a&#39;}Q(S_{t+1},a&#39;;\\theta^-) $$</p><p>自然终止时只保留即时奖励。(\\theta^-) 表示目标网络参数。</p><h3 id="_3-3-只回归被执行动作的价值" tabindex="-1">3.3 只回归被执行动作的价值 <a class="header-anchor" href="#_3-3-只回归被执行动作的价值" aria-label="Permalink to &quot;3.3 只回归被执行动作的价值&quot;">​</a></h3><p>在线网络输出全部动作，但当前样本只监督 (A_t) 对应的值：</p><p>$$ L(\\theta)=\\mathbb E\\left[\\ell\\left(Y_t-Q(S_t,A_t;\\theta)\\right)\\right] $$</p><p>其他动作输出不会被这一条样本直接设定标签，却会因共享隐藏层间接受影响。</p><h3 id="_3-4-损失函数不能替代正确目标" tabindex="-1">3.4 损失函数不能替代正确目标 <a class="header-anchor" href="#_3-4-损失函数不能替代正确目标" aria-label="Permalink to &quot;3.4 损失函数不能替代正确目标&quot;">​</a></h3><p>Mean Squared Error（均方误差）和 Huber Loss（胡伯损失）都可用于回归。胡伯损失对大误差更稳健，但若终止掩码、奖励尺度或目标公式写错，换损失函数无法修复语义错误。</p><p><img src="'+o+'" alt="DQN 目标由奖励、终止掩码和目标网络最大值构成"></p><h2 id="四、为什么直接用同一个网络会不稳定" tabindex="-1">四、为什么直接用同一个网络会不稳定 <a class="header-anchor" href="#四、为什么直接用同一个网络会不稳定" aria-label="Permalink to &quot;四、为什么直接用同一个网络会不稳定&quot;">​</a></h2><h3 id="_4-1-预测和标签会同时移动" tabindex="-1">4.1 预测和标签会同时移动 <a class="header-anchor" href="#_4-1-预测和标签会同时移动" aria-label="Permalink to &quot;4.1 预测和标签会同时移动&quot;">​</a></h3><p>若在线网络既输出当前预测又生成下一状态目标，一次参数更新会同时改变等式两端。模型追逐的标签不断移动，误差下降方向可能很快失效。</p><h3 id="_4-2-最大化会放大估计噪声" tabindex="-1">4.2 最大化会放大估计噪声 <a class="header-anchor" href="#_4-2-最大化会放大估计噪声" aria-label="Permalink to &quot;4.2 最大化会放大估计噪声&quot;">​</a></h3><p>目标选择所有动作估计中的最大值。即使各动作误差均值接近零，最大值也更容易选中被正向高估的动作，长期可能形成过高价值目标。</p><h3 id="_4-3-策略还会改变数据分布" tabindex="-1">4.3 策略还会改变数据分布 <a class="header-anchor" href="#_4-3-策略还会改变数据分布" aria-label="Permalink to &quot;4.3 策略还会改变数据分布&quot;">​</a></h3><p>Q 值改变后，ε-贪心行为随之改变，随后进入缓冲区的状态和动作也改变。模型、目标与采样分布构成相互反馈，而不是固定数据集上的回归。</p><h2 id="五、目标网络怎样减慢目标变化" tabindex="-1">五、目标网络怎样减慢目标变化 <a class="header-anchor" href="#五、目标网络怎样减慢目标变化" aria-label="Permalink to &quot;五、目标网络怎样减慢目标变化&quot;">​</a></h2><h3 id="_5-1-在线网络承担学习和行为决策" tabindex="-1">5.1 在线网络承担学习和行为决策 <a class="header-anchor" href="#_5-1-在线网络承担学习和行为决策" aria-label="Permalink to &quot;5.1 在线网络承担学习和行为决策&quot;">​</a></h3><p>参数 (\\theta) 每次优化都更新，并常用于选择交互动作。它代表当前正在快速变化的价值估计。</p><h3 id="_5-2-目标网络只生成自举部分" tabindex="-1">5.2 目标网络只生成自举部分 <a class="header-anchor" href="#_5-2-目标网络只生成自举部分" aria-label="Permalink to &quot;5.2 目标网络只生成自举部分&quot;">​</a></h3><p>参数 (\\theta^-) 在若干更新内保持不变，不参与当前损失的反向传播。实现时必须对目标分支停止梯度，否则网络仍会试图同时修改标签。</p><h3 id="_5-3-硬同步按固定间隔复制参数" tabindex="-1">5.3 硬同步按固定间隔复制参数 <a class="header-anchor" href="#_5-3-硬同步按固定间隔复制参数" aria-label="Permalink to &quot;5.3 硬同步按固定间隔复制参数&quot;">​</a></h3><p>经典做法每隔若干环境步或梯度步执行 (\\theta^-\\leftarrow\\theta)。同步过快会失去稳定作用，同步过慢则可能使用严重过时的目标。</p><h3 id="_5-4-软同步是后续常见变体" tabindex="-1">5.4 软同步是后续常见变体 <a class="header-anchor" href="#_5-4-软同步是后续常见变体" aria-label="Permalink to &quot;5.4 软同步是后续常见变体&quot;">​</a></h3><p>Soft Update（软更新）写作 (\\theta^-\\leftarrow\\tau\\theta+(1-\\tau)\\theta^-)。它不是经典 DQN 唯一实现，比较实验必须报告同步方式和计数单位。</p><p><img src="'+l+'" alt="在线网络持续学习，目标网络延迟同步"></p><h2 id="六、连续采样为什么不能直接成批训练" tabindex="-1">六、连续采样为什么不能直接成批训练 <a class="header-anchor" href="#六、连续采样为什么不能直接成批训练" aria-label="Permalink to &quot;六、连续采样为什么不能直接成批训练&quot;">​</a></h2><h3 id="_6-1-相邻观测通常高度相关" tabindex="-1">6.1 相邻观测通常高度相关 <a class="header-anchor" href="#_6-1-相邻观测通常高度相关" aria-label="Permalink to &quot;6.1 相邻观测通常高度相关&quot;">​</a></h3><p>车辆在相邻控制周期的位置和速度变化很小，连续画面也近似重复。直接用最新一段轨迹训练，梯度会被局部场景主导。</p><h3 id="_6-2-在线策略造成非平稳数据" tabindex="-1">6.2 在线策略造成非平稳数据 <a class="header-anchor" href="#_6-2-在线策略造成非平稳数据" aria-label="Permalink to &quot;6.2 在线策略造成非平稳数据&quot;">​</a></h3><p>训练早期大多随机探索，后期更多利用当前策略。不同时间的数据分布不同，网络并不是从固定分布持续抽样。</p><h3 id="_6-3-罕见事件容易被新样本覆盖" tabindex="-1">6.3 罕见事件容易被新样本覆盖 <a class="header-anchor" href="#_6-3-罕见事件容易被新样本覆盖" aria-label="Permalink to &quot;6.3 罕见事件容易被新样本覆盖&quot;">​</a></h3><p>有限窗口若只保留最新转移，一次急刹或成功避障很快会被大量普通巡航样本淹没。缓冲区至少给旧经验留下重复使用的机会。</p><h2 id="七、经验回放到底解决什么" tabindex="-1">七、经验回放到底解决什么 <a class="header-anchor" href="#七、经验回放到底解决什么" aria-label="Permalink to &quot;七、经验回放到底解决什么&quot;">​</a></h2><h3 id="_7-1-把采集顺序与学习顺序分开" tabindex="-1">7.1 把采集顺序与学习顺序分开 <a class="header-anchor" href="#_7-1-把采集顺序与学习顺序分开" aria-label="Permalink to &quot;7.1 把采集顺序与学习顺序分开&quot;">​</a></h3><p>每次交互先把转移写入缓冲区，优化时再随机抽取 Mini-batch（小批量）。训练样本因此不必严格按照发生顺序进入网络。</p><h3 id="_7-2-一条经验可以被使用多次" tabindex="-1">7.2 一条经验可以被使用多次 <a class="header-anchor" href="#_7-2-一条经验可以被使用多次" aria-label="Permalink to &quot;7.2 一条经验可以被使用多次&quot;">​</a></h3><p>环境交互通常比一次梯度计算昂贵。回放允许同一转移在多个批次中出现，提高样本利用率，也使离线日志与在线经验具有相似的数据接口。</p><h3 id="_7-3-缓冲区带来陈旧数据" tabindex="-1">7.3 缓冲区带来陈旧数据 <a class="header-anchor" href="#_7-3-缓冲区带来陈旧数据" aria-label="Permalink to &quot;7.3 缓冲区带来陈旧数据&quot;">​</a></h3><p>旧转移由过去的行为策略产生，可能与当前策略访问区域不同。DQN 是异策略算法，可以利用这些数据，但过度陈旧、覆盖失衡和环境变化仍会影响训练。</p><h3 id="_7-4-均匀抽样不是风险均匀" tabindex="-1">7.4 均匀抽样不是风险均匀 <a class="header-anchor" href="#_7-4-均匀抽样不是风险均匀" aria-label="Permalink to &quot;7.4 均匀抽样不是风险均匀&quot;">​</a></h3><p>普通巡航数量巨大，碰撞前兆数量稀少。均匀回放按样本数量分配概率，不会自动照顾安全关键事件；进阶篇会讨论优先经验回放以及它引入的偏差修正。</p><p><img src="'+n+'" alt="经验回放分离环境时间顺序与随机学习批次"></p><h2 id="八、探索策略怎样产生训练数据" tabindex="-1">八、探索策略怎样产生训练数据 <a class="header-anchor" href="#八、探索策略怎样产生训练数据" aria-label="Permalink to &quot;八、探索策略怎样产生训练数据&quot;">​</a></h2><h3 id="_8-1-纯贪心会过早锁定动作" tabindex="-1">8.1 纯贪心会过早锁定动作 <a class="header-anchor" href="#_8-1-纯贪心会过早锁定动作" aria-label="Permalink to &quot;8.1 纯贪心会过早锁定动作&quot;">​</a></h3><p>初始 Q 值几乎随机，纯贪心可能因为微小误差反复选择同一动作。未尝试动作缺少数据，其价值也无法得到可靠比较。</p><h3 id="_8-2-ε-贪心混合探索与利用" tabindex="-1">8.2 ε-贪心混合探索与利用 <a class="header-anchor" href="#_8-2-ε-贪心混合探索与利用" aria-label="Permalink to &quot;8.2 ε-贪心混合探索与利用&quot;">​</a></h3><p>以概率 ε 随机选动作，以概率 (1-\\varepsilon) 选择最大 Q 值动作。训练中常逐渐衰减 ε，但不应在缓冲区尚无足够覆盖时过早降到很低。</p><h3 id="_8-3-随机动作不等于安全探索" tabindex="-1">8.3 随机动作不等于安全探索 <a class="header-anchor" href="#_8-3-随机动作不等于安全探索" aria-label="Permalink to &quot;8.3 随机动作不等于安全探索&quot;">​</a></h3><p>自动驾驶中的随机换道或随机制动可能不可接受。动作掩码、规则约束、仿真环境和安全屏蔽需要在探索层面限制可执行集合，不能把 ε 调小当成安全保证。</p><h2 id="九、完整训练循环怎样连接起来" tabindex="-1">九、完整训练循环怎样连接起来 <a class="header-anchor" href="#九、完整训练循环怎样连接起来" aria-label="Permalink to &quot;九、完整训练循环怎样连接起来&quot;">​</a></h2><h3 id="_9-1-初始化两个网络和缓冲区" tabindex="-1">9.1 初始化两个网络和缓冲区 <a class="header-anchor" href="#_9-1-初始化两个网络和缓冲区" aria-label="Permalink to &quot;9.1 初始化两个网络和缓冲区&quot;">​</a></h3><p>在线网络随机初始化，目标网络复制在线参数。缓冲区为空，训练通常先经历 Replay Warm-up（回放预热），避免用极少且高度相关的数据立即更新。</p><h3 id="_9-2-环境步负责采集" tabindex="-1">9.2 环境步负责采集 <a class="header-anchor" href="#_9-2-环境步负责采集" aria-label="Permalink to &quot;9.2 环境步负责采集&quot;">​</a></h3><p>根据在线网络和 ε-贪心选择动作，执行环境转移，区分自然终止与外部截断，再把必要字段写入缓冲区。</p><h3 id="_9-3-梯度步负责学习" tabindex="-1">9.3 梯度步负责学习 <a class="header-anchor" href="#_9-3-梯度步负责学习" aria-label="Permalink to &quot;9.3 梯度步负责学习&quot;">​</a></h3><p>从缓冲区采样批次，用目标网络计算停止梯度的 Bellman 目标，用在线网络计算被执行动作的预测，反向传播损失并更新 (\\theta)。</p><h3 id="_9-4-同步和评估各有独立时钟" tabindex="-1">9.4 同步和评估各有独立时钟 <a class="header-anchor" href="#_9-4-同步和评估各有独立时钟" aria-label="Permalink to &quot;9.4 同步和评估各有独立时钟&quot;">​</a></h3><p>目标网络同步间隔可能按环境步计数，优化频率可能每若干环境步执行一次，评估则按完整回合运行。代码和实验记录必须写清各自单位。</p><p><img src="'+d+'" alt="DQN 从交互、回放到目标同步的完整闭环"></p><h2 id="十、图像输入为什么需要时间信息" tabindex="-1">十、图像输入为什么需要时间信息 <a class="header-anchor" href="#十、图像输入为什么需要时间信息" aria-label="Permalink to &quot;十、图像输入为什么需要时间信息&quot;">​</a></h2><h3 id="_10-1-单帧无法推断运动方向" tabindex="-1">10.1 单帧无法推断运动方向 <a class="header-anchor" href="#_10-1-单帧无法推断运动方向" aria-label="Permalink to &quot;10.1 单帧无法推断运动方向&quot;">​</a></h3><p>一张图能看见车辆位置，却难以区分它正在接近还是远离。原始 Atari DQN 堆叠连续帧，就是为了让网络获得速度和方向线索。</p><h3 id="_10-2-预处理改变了状态定义" tabindex="-1">10.2 预处理改变了状态定义 <a class="header-anchor" href="#_10-2-预处理改变了状态定义" aria-label="Permalink to &quot;10.2 预处理改变了状态定义&quot;">​</a></h3><p>灰度化、缩放、帧跳过与帧堆叠不只是加速手段，它们决定智能体能观察什么。不同预处理流水线的结果不能在没有说明时直接比较。</p><h3 id="_10-3-自动驾驶通常需要多模态历史" tabindex="-1">10.3 自动驾驶通常需要多模态历史 <a class="header-anchor" href="#_10-3-自动驾驶通常需要多模态历史" aria-label="Permalink to &quot;10.3 自动驾驶通常需要多模态历史&quot;">​</a></h3><p>传感器检测、地图、规划参考线和车辆动力学状态具有不同频率与延迟。仅把当前检测框送入 DQN，可能破坏近似马尔可夫性，需要时间窗口或状态估计补足。</p><h2 id="十一、终止与截断为什么必须分开" tabindex="-1">十一、终止与截断为什么必须分开 <a class="header-anchor" href="#十一、终止与截断为什么必须分开" aria-label="Permalink to &quot;十一、终止与截断为什么必须分开&quot;">​</a></h2><h3 id="_11-1-自然终止没有后续回报" tabindex="-1">11.1 自然终止没有后续回报 <a class="header-anchor" href="#_11-1-自然终止没有后续回报" aria-label="Permalink to &quot;11.1 自然终止没有后续回报&quot;">​</a></h3><p>达到任务成功、失败或环境定义的终止状态时，目标为 (Y_t=R_{t+1})，不再自举下一状态价值。</p><h3 id="_11-2-外部时间截断不一定终结任务语义" tabindex="-1">11.2 外部时间截断不一定终结任务语义 <a class="header-anchor" href="#_11-2-外部时间截断不一定终结任务语义" aria-label="Permalink to &quot;11.2 外部时间截断不一定终结任务语义&quot;">​</a></h3><p>若只是训练器达到步数上限，物理过程本可继续，通常仍应使用下一状态价值。把截断统一当作终止，会低估接近时间上限的状态。</p><h3 id="_11-3-有限时域任务需要剩余时间状态" tabindex="-1">11.3 有限时域任务需要剩余时间状态 <a class="header-anchor" href="#_11-3-有限时域任务需要剩余时间状态" aria-label="Permalink to &quot;11.3 有限时域任务需要剩余时间状态&quot;">​</a></h3><p>若时间限制本身就是任务定义的一部分，剩余时间应进入观测以保持马尔可夫性，并在时域结束时按真正终止处理。</p><h2 id="十二、训练频率与数据比例怎样理解" tabindex="-1">十二、训练频率与数据比例怎样理解 <a class="header-anchor" href="#十二、训练频率与数据比例怎样理解" aria-label="Permalink to &quot;十二、训练频率与数据比例怎样理解&quot;">​</a></h2><h3 id="_12-1-环境步和梯度步不是同一个量" tabindex="-1">12.1 环境步和梯度步不是同一个量 <a class="header-anchor" href="#_12-1-环境步和梯度步不是同一个量" aria-label="Permalink to &quot;12.1 环境步和梯度步不是同一个量&quot;">​</a></h3><p>每采集一步训练一次只是一个选择。可以每四步训练一次，也可以每个环境步进行多次更新，后者会提高 Update-to-Data Ratio（更新数据比）。</p><h3 id="_12-2-更新过少会浪费数据" tabindex="-1">12.2 更新过少会浪费数据 <a class="header-anchor" href="#_12-2-更新过少会浪费数据" aria-label="Permalink to &quot;12.2 更新过少会浪费数据&quot;">​</a></h3><p>缓冲区积累大量经验却很少优化，模型跟不上数据变化，训练时间主要耗在环境交互。</p><h3 id="_12-3-更新过多会过拟合回放分布" tabindex="-1">12.3 更新过多会过拟合回放分布 <a class="header-anchor" href="#_12-3-更新过多会过拟合回放分布" aria-label="Permalink to &quot;12.3 更新过多会过拟合回放分布&quot;">​</a></h3><p>对同一批有限数据反复优化，TD 误差可以下降，但策略性能可能停滞甚至退化。需要联合观察数据新鲜度、价值范围和独立评估回报。</p><h2 id="十三、训练过程应该监控什么" tabindex="-1">十三、训练过程应该监控什么 <a class="header-anchor" href="#十三、训练过程应该监控什么" aria-label="Permalink to &quot;十三、训练过程应该监控什么&quot;">​</a></h2><h3 id="_13-1-回报只说明结果-不说明内部状态" tabindex="-1">13.1 回报只说明结果，不说明内部状态 <a class="header-anchor" href="#_13-1-回报只说明结果-不说明内部状态" aria-label="Permalink to &quot;13.1 回报只说明结果，不说明内部状态&quot;">​</a></h3><p>训练与评估回报要分开。训练回报包含探索噪声，评估应冻结参数、关闭或固定探索，并使用独立随机种子。</p><h3 id="_13-2-损失不能单独作为成功标准" tabindex="-1">13.2 损失不能单独作为成功标准 <a class="header-anchor" href="#_13-2-损失不能单独作为成功标准" aria-label="Permalink to &quot;13.2 损失不能单独作为成功标准&quot;">​</a></h3><p>目标也在变化，损失上升可能来自发现高奖励区域，损失下降也可能来自价值整体塌缩。它必须与回报、Q 值均值、最大值和 TD 误差分布一起看。</p><h3 id="_13-3-数据覆盖需要被显式记录" tabindex="-1">13.3 数据覆盖需要被显式记录 <a class="header-anchor" href="#_13-3-数据覆盖需要被显式记录" aria-label="Permalink to &quot;13.3 数据覆盖需要被显式记录&quot;">​</a></h3><p>记录动作频率、终止原因、缓冲区年龄、状态关键区间和安全事件。若某动作几乎从不出现，对应 Q 值就缺少数据支持。</p><h3 id="_13-4-多随机种子比最好曲线更可信" tabindex="-1">13.4 多随机种子比最好曲线更可信 <a class="header-anchor" href="#_13-4-多随机种子比最好曲线更可信" aria-label="Permalink to &quot;13.4 多随机种子比最好曲线更可信&quot;">​</a></h3><p>深度强化学习对初始化、探索轨迹和环境随机性敏感。应报告多个种子的中位数、分散程度和失败运行，而不是只展示最顺滑的一条曲线。</p><h2 id="十四、dqn-的主要适用边界" tabindex="-1">十四、DQN 的主要适用边界 <a class="header-anchor" href="#十四、dqn-的主要适用边界" aria-label="Permalink to &quot;十四、DQN 的主要适用边界&quot;">​</a></h2><h3 id="_14-1-动作集合必须可穷举" tabindex="-1">14.1 动作集合必须可穷举 <a class="header-anchor" href="#_14-1-动作集合必须可穷举" aria-label="Permalink to &quot;14.1 动作集合必须可穷举&quot;">​</a></h3><p>输出层要比较每个动作，动作数量过大时计算和探索都会困难。连续动作不能直接依赖有限输出最大值。</p><h3 id="_14-2-样本效率仍然有限" tabindex="-1">14.2 样本效率仍然有限 <a class="header-anchor" href="#_14-2-样本效率仍然有限" aria-label="Permalink to &quot;14.2 样本效率仍然有限&quot;">​</a></h3><p>经验回放提高复用，不代表 DQN 只需少量数据。高维感知、稀疏奖励和多场景覆盖仍可能需要大量交互。</p><h3 id="_14-3-价值估计可能系统性高估" tabindex="-1">14.3 价值估计可能系统性高估 <a class="header-anchor" href="#_14-3-价值估计可能系统性高估" aria-label="Permalink to &quot;14.3 价值估计可能系统性高估&quot;">​</a></h3><p>最大化操作会选择估计噪声中偏高的动作。下一篇的 Double DQN（双深度 Q 网络）会分离动作选择与价值评估，缓解这一偏差。</p><h3 id="_14-4-环境变化会让旧数据失效" tabindex="-1">14.4 环境变化会让旧数据失效 <a class="header-anchor" href="#_14-4-环境变化会让旧数据失效" aria-label="Permalink to &quot;14.4 环境变化会让旧数据失效&quot;">​</a></h3><p>传感器版本、交通规则或奖励函数改变后，缓冲区中的旧转移可能不再来自同一个问题。继续混用数据必须先确认状态、动作和奖励语义一致。</p><h2 id="十五、自动驾驶中怎样合理使用-dqn" tabindex="-1">十五、自动驾驶中怎样合理使用 DQN <a class="header-anchor" href="#十五、自动驾驶中怎样合理使用-dqn" aria-label="Permalink to &quot;十五、自动驾驶中怎样合理使用 DQN&quot;">​</a></h2><h3 id="_15-1-更适合有限高层决策" tabindex="-1">15.1 更适合有限高层决策 <a class="header-anchor" href="#_15-1-更适合有限高层决策" aria-label="Permalink to &quot;15.1 更适合有限高层决策&quot;">​</a></h3><p>例如保持车道、向左换道、向右换道、让行等有限动作，可以由 DQN 评估；动作再交给经过约束的轨迹规划与控制模块执行。</p><h3 id="_15-2-不应直接把网络输出当作执行器命令" tabindex="-1">15.2 不应直接把网络输出当作执行器命令 <a class="header-anchor" href="#_15-2-不应直接把网络输出当作执行器命令" aria-label="Permalink to &quot;15.2 不应直接把网络输出当作执行器命令&quot;">​</a></h3><p>离散决策到车辆执行之间还存在可行性检查、轨迹生成、动力学约束和底盘延迟。文章中的动作价值高不等于该动作当前可安全执行。</p><h3 id="_15-3-仿真回报不代表道路安全" tabindex="-1">15.3 仿真回报不代表道路安全 <a class="header-anchor" href="#_15-3-仿真回报不代表道路安全" aria-label="Permalink to &quot;15.3 仿真回报不代表道路安全&quot;">​</a></h3><p>碰撞率、最小间距、舒适性、规则违例和人工接管都应独立评估。高平均回报不能覆盖低概率高后果失败。</p><h2 id="十六、一个最小可复现实验怎么搭" tabindex="-1">十六、一个最小可复现实验怎么搭 <a class="header-anchor" href="#十六、一个最小可复现实验怎么搭" aria-label="Permalink to &quot;十六、一个最小可复现实验怎么搭&quot;">​</a></h2><h3 id="_16-1-从低维离散动作环境开始" tabindex="-1">16.1 从低维离散动作环境开始 <a class="header-anchor" href="#_16-1-从低维离散动作环境开始" aria-label="Permalink to &quot;16.1 从低维离散动作环境开始&quot;">​</a></h3><p>选 CartPole（倒立摆小车）或离散速度控制任务，先固定网络规模、奖励、缓冲区容量、预热步数、批量大小、同步间隔和 ε 计划。</p><h3 id="_16-2-逐项加入稳定机制" tabindex="-1">16.2 逐项加入稳定机制 <a class="header-anchor" href="#_16-2-逐项加入稳定机制" aria-label="Permalink to &quot;16.2 逐项加入稳定机制&quot;">​</a></h3><p>用同一随机种子分别运行无回放、仅回放、回放加目标网络，观察价值范围与回报。消融实验比只展示完整版更能解释每个组件的作用。</p><h3 id="_16-3-保存能够复核的训练记录" tabindex="-1">16.3 保存能够复核的训练记录 <a class="header-anchor" href="#_16-3-保存能够复核的训练记录" aria-label="Permalink to &quot;16.3 保存能够复核的训练记录&quot;">​</a></h3><p>至少保存配置、代码版本、随机种子、环境步数、评估协议和终止统计。只保存最终模型而没有训练上下文，难以判断结果是否可重复。</p><h2 id="十七、最常见的实现错误" tabindex="-1">十七、最常见的实现错误 <a class="header-anchor" href="#十七、最常见的实现错误" aria-label="Permalink to &quot;十七、最常见的实现错误&quot;">​</a></h2><h3 id="_17-1-没有从目标分支停止梯度" tabindex="-1">17.1 没有从目标分支停止梯度 <a class="header-anchor" href="#_17-1-没有从目标分支停止梯度" aria-label="Permalink to &quot;17.1 没有从目标分支停止梯度&quot;">​</a></h3><p>目标网络参数通常不进入优化器，目标张量也应脱离计算图。否则会浪费计算，甚至改变预期更新路径。</p><h3 id="_17-2-动作索引维度取错" tabindex="-1">17.2 动作索引维度取错 <a class="header-anchor" href="#_17-2-动作索引维度取错" aria-label="Permalink to &quot;17.2 动作索引维度取错&quot;">​</a></h3><p>网络输出形状通常为“批量大小乘动作数”，需要按每条样本的动作索引提取标量。错误广播可能让所有动作同时拟合同一目标。</p><h3 id="_17-3-同步间隔计数单位混乱" tabindex="-1">17.3 同步间隔计数单位混乱 <a class="header-anchor" href="#_17-3-同步间隔计数单位混乱" aria-label="Permalink to &quot;17.3 同步间隔计数单位混乱&quot;">​</a></h3><p>把论文中的环境步误当梯度步，在不同训练频率下会得到完全不同的目标滞后。配置名应写清 <code>target_update_env_steps</code> 或对应含义。</p><h3 id="_17-4-评估仍在写入缓冲区或更新网络" tabindex="-1">17.4 评估仍在写入缓冲区或更新网络 <a class="header-anchor" href="#_17-4-评估仍在写入缓冲区或更新网络" aria-label="Permalink to &quot;17.4 评估仍在写入缓冲区或更新网络&quot;">​</a></h3><p>评估循环应与训练状态隔离。若评估轨迹继续改变缓冲区、归一化统计或参数，所谓独立评估就已经被污染。</p><h2 id="十八、学到什么程度才算真正掌握" tabindex="-1">十八、学到什么程度才算真正掌握 <a class="header-anchor" href="#十八、学到什么程度才算真正掌握" aria-label="Permalink to &quot;十八、学到什么程度才算真正掌握&quot;">​</a></h2><h3 id="_18-1-能画出数据与梯度路径" tabindex="-1">18.1 能画出数据与梯度路径 <a class="header-anchor" href="#_18-1-能画出数据与梯度路径" aria-label="Permalink to &quot;18.1 能画出数据与梯度路径&quot;">​</a></h3><p>应能说明动作由哪个网络选择，样本何时进入缓冲区，目标由哪个网络计算，梯度只更新哪些参数，以及目标网络何时同步。</p><h3 id="_18-2-能解释每个稳定机制的有限作用" tabindex="-1">18.2 能解释每个稳定机制的有限作用 <a class="header-anchor" href="#_18-2-能解释每个稳定机制的有限作用" aria-label="Permalink to &quot;18.2 能解释每个稳定机制的有限作用&quot;">​</a></h3><p>经验回放降低相关并复用数据，目标网络减慢目标移动，ε-贪心增加动作覆盖。它们都不是收敛证明，也不是安全保证。</p><h3 id="_18-3-能从异常指标定位方向" tabindex="-1">18.3 能从异常指标定位方向 <a class="header-anchor" href="#_18-3-能从异常指标定位方向" aria-label="Permalink to &quot;18.3 能从异常指标定位方向&quot;">​</a></h3><p>Q 值暴涨应检查奖励尺度、终止掩码与最大化偏差；回报停滞应检查探索和覆盖；损失很低但策略很差，应检查数据分布和目标退化。</p><h3 id="_18-4-能准备进入进阶改造" tabindex="-1">18.4 能准备进入进阶改造 <a class="header-anchor" href="#_18-4-能准备进入进阶改造" aria-label="Permalink to &quot;18.4 能准备进入进阶改造&quot;">​</a></h3><p>下一篇将沿着“高估、表示、采样、探索”四个问题，分别讲清 Double DQN、Dueling DQN（竞争深度 Q 网络）、Prioritized Experience Replay（优先经验回放）与 Noisy Network（噪声网络）。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter6/chapter6.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第六章深度 Q 网络</a></p><p><a href="https://www.nature.com/articles/nature14236" target="_blank" rel="noreferrer">DeepMind《Human-level control through deep reinforcement learning》</a></p><p><a href="https://arxiv.org/abs/1312.5602" target="_blank" rel="noreferrer">DeepMind《Playing Atari with Deep Reinforcement Learning》</a></p><p><a href="https://gymnasium.farama.org/tutorials/gymnasium_basics/handling_time_limits/" target="_blank" rel="noreferrer">Gymnasium 关于终止与时间截断的官方说明</a></p><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版</a></p>',162)])])}const k=e(s,[["render",c]]);export{f as __pageData,k as default};
